<script setup lang="ts">
import type { TaskStatus, Priority, Todo } from '~/types/tracker'
const tracker = useTracker(); const { data, load, addTask, addLog, save } = tracker
const screen = ref('dashboard'); const month = ref(new Date().toISOString().slice(0,7)); const modal = ref(''); const search = ref(''); const dark = ref(false); const collapsed = ref(false); const profileOpen = ref(false); const toast = ref(''); const importOpen = ref(false); const importPreview = ref(''); const pendingFile = ref<File|null>(null); const importRows = ref<Array<{month:string,project:string,category:string,task:string,owner:string,hours:number,status:TaskStatus,priority:Priority}>>([]); const importedMonth = ref(''); const timer = ref<number|null>(null); const elapsed = ref(0); const logMode = ref<'manual'|'timer'>('manual'); const importedTaskCount = ref(0)
watch(importPreview, preview => { if (!preview || !pendingFile.value?.name.toLowerCase().endsWith('.csv') || preview.startsWith('CSV preview')) return; const raw = preview.split('\n\n').slice(1).join('\n\n'); importRows.value = raw.split(/\r?\n/).filter(Boolean).map(line => { const cells = line.split(',').map(cell => cell.replace(/^"|"$/g, '').trim()); return { month: cells[0] || month.value, project: cells[1] || 'Imported', category: cells[2] || 'General', task: cells[3] || 'Imported task', owner: cells[4] || '', hours: Number(cells[5]) || 0, status: (cells[6] || 'In Progress') as TaskStatus, priority: (cells[7] || 'Medium') as Priority } }); importedMonth.value = importRows.value[0]?.month || month.value; importPreview.value = `CSV preview\n${importRows.value.length} records detected\nMonths: ${[...new Set(importRows.value.map(row => row.month))].join(', ')}\n\n${importRows.value.slice(0, 8).map(row => `${row.month} · ${row.project} · ${row.category} · ${row.task} · ${row.hours}h`).join('\n')}` })
watch(() => data.value.tasks.length, count => { if (count > importedTaskCount.value && importedMonth.value) month.value = importedMonth.value; importedTaskCount.value = count })
const task = ref({project:'',category:'',task:'',owner:'',hours:0,status:'In Progress' as TaskStatus,priority:'Medium' as Priority}); const todo=ref({title:'',detail:'',due:'',status:'Pending' as Todo['status'],priority:'Medium' as Priority}); const months=Array.from({length:12},(_,i)=>`${new Date().getFullYear()}-${String(i+1).padStart(2,'0')}`)
const monthLabel=computed(()=>new Date(`${month.value}-01`).toLocaleDateString('en-US',{month:'long',year:'numeric'})); const monthTasks=computed(()=>data.value.tasks.filter(t=>t.month===month.value&&Object.values(t).join(' ').toLowerCase().includes(search.value.toLowerCase()))); const hours=computed(()=>monthTasks.value.reduce((s,t)=>s+Number(t.hours||0),0)); const done=computed(()=>monthTasks.value.filter(t=>t.status==='Completed').length); const dailyHours=computed(()=>Array.from({length:7},(_,i)=>monthTasks.value.filter(t=>t.due===new Date(Date.now()-((6-i)*86400000)).toISOString().slice(0,10)).reduce((s,t)=>s+Number(t.hours||0),0))); const weeklyHours=computed(()=>[0,1,2,3].map(week=>monthTasks.value.filter(t=>{const day=Number(t.due?.slice(-2)||0);return day>week*7&&day<week*7+8}).reduce((s,t)=>s+Number(t.hours||0),0))); const monthlyHours=computed(()=>months.map(m=>data.value.tasks.filter(t=>t.month===m).reduce((s,t)=>s+Number(t.hours||0),0))); const chartRange=ref('day'); const notice=(v:string)=>{toast.value=v;setTimeout(()=>toast.value='',2200)}; const tone=(v:string)=>v.toLowerCase().replaceAll(' ','-'); const shift=(n:number)=>{month.value=months[Math.max(0,Math.min(11,months.indexOf(month.value)+n))]}
const saveTask=()=>{addTask({...task.value,month:month.value});modal.value='';notice('Time entry added');task.value={project:'',category:'',task:'',owner:'',hours:0,status:'In Progress',priority:'Medium'}}
const saveManualLog=()=>{addLog({date:new Date().toISOString().slice(0,10),user:'TEZ',text:`${task.value.task||'Work session'} · ${task.value.hours||0} hours · ${task.value.project||'No project'}`});modal.value='';notice('Manual log added')}
const startTimer=()=>{if(timer.value)return;timer.value=window.setInterval(()=>elapsed.value++,1000);notice('Timer started')}; const stopTimer=()=>{if(timer.value){clearInterval(timer.value);timer.value=null;task.value.hours=Math.round(elapsed.value/3600*100)/100;saveManualLog();elapsed.value=0;notice('Timer stopped and logged')}}
const addTodo=()=>{data.value.todos.push({...todo.value,id:crypto.randomUUID()});save();modal.value='';notice('To-do added');todo.value={title:'',detail:'',due:'',status:'Pending',priority:'Medium'}}; const dragId=ref(''); const dragStart=(x:Todo)=>dragId.value=x.id; const dropTodo=(status:Todo['status'])=>{const x=data.value.todos.find(t=>t.id===dragId.value);if(x){x.status=status;save();notice(`Moved to ${status}`)}}
const pickImport=(e:Event)=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;pendingFile.value=file;const reader=new FileReader();reader.onload=()=>{importPreview.value=`${file.name}\n${file.type||'unknown format'}\n\n${String(reader.result).slice(0,900)}`;importOpen.value=true};reader.readAsText(file)}; const applyImport=()=>{const file=pendingFile.value;if(!file)return;const reader=new FileReader();reader.onload=()=>{const raw=String(reader.result);try{if(file.name.toLowerCase().endsWith('.json'))data.value={...data.value,...JSON.parse(raw)};else if(file.name.toLowerCase().endsWith('.csv'))raw.split(/\r?\n/).slice(1).filter(Boolean).forEach(line=>{const c=line.split(',');data.value.tasks.push({id:crypto.randomUUID(),month:c[0]||month.value,project:c[1]||'Imported',category:c[2]||'General',task:c[3]||'Imported task',owner:c[4]||'',hours:Number(c[5])||0,status:(c[6]||'In Progress') as TaskStatus,priority:(c[7]||'Medium') as Priority})});else data.value.logs.push({id:crypto.randomUUID(),date:new Date().toISOString().slice(0,10),user:'TEZ',text:`Imported ${file.name}; review required`});save();importOpen.value=false;notice('Records imported into source months')}catch{notice('Could not analyze this file')}};reader.readAsText(file)}
const exportCsv=()=>{const rows=[['Month','Project','Category','Task','Owner','Hours','Status','Priority'],...data.value.tasks.filter(t=>t.month===month.value).map(t=>[t.month,t.project,t.category,t.task,t.owner,t.hours,t.status,t.priority])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));a.download='my-tracker.csv';a.click();modal.value='';notice('Report exported')}; const selectChartRange=(range:string)=>{chartRange.value=range;const chart=document.querySelector('.analytics-card');if(chart){chart.setAttribute('data-range',range);const label=chart.querySelector('.chart-range-label');if(label)label.textContent=`${range[0].toUpperCase()+range.slice(1)} trend`}}; onMounted(()=>{load();setTimeout(()=>{const card=document.querySelector('.analytics-card');const head=card?.querySelector('.panel-head');if(card&&head&&!head.querySelector('.chart-filters')){const filters=document.createElement('div');filters.className='chart-filters';['day','week','month'].forEach(range=>{const button=document.createElement('button');button.type='button';button.textContent=range[0].toUpperCase()+range.slice(1);button.className=range==='day'?'active':'';button.onclick=()=>{filters.querySelectorAll('button').forEach(item=>item.classList.remove('active'));button.classList.add('active');selectChartRange(range)};filters.appendChild(button)});head.appendChild(filters);const label=card.querySelector('.panel-head p');if(label)label.classList.add('chart-range-label');const ring=card.querySelector('.todo-ring');const work=card.closest('.dashboard-grid')?.querySelector('.panel');if(ring&&work){ring.classList.add('work-flight-donut');work.appendChild(ring)}}},0)})
</script>

<template><div class="app-shell" :class="[{dark},{'sidebar-collapsed':collapsed}]"><aside class="sidebar"><div class="logo"><span>MT</span><div><b>my tracker</b><small>work ecosystem</small></div></div><p class="nav-label">WORKSPACE</p><nav><button v-for="item in [{id:'dashboard',label:'Overview',icon:'⌂'},{id:'logs',label:'My timesheets / logs',icon:'▤'},{id:'todos',label:'To-dos',icon:'✓'},{id:'calendar',label:'Calendar',icon:'▦'},{id:'meetings',label:'Meetings',icon:'◫'},{id:'feedback',label:'Feedback / notes',icon:'✦'},{id:'reports',label:'Reports',icon:'▥'},{id:'integrations',label:'Integrations',icon:'◎'}]" :key="item.id" :class="{active:screen===item.id}" @click="screen=item.id">{{item.icon}} <span>{{item.label}}</span></button></nav><div class="sidebar-bottom">Saved locally<br><small>Google Calendar · Outlook ready</small></div></aside><section class="app-main"><header class="topbar"><button class="collapse-button" @click="collapsed=!collapsed">☰</button><div class="top-search">⌕ <input v-model="search" placeholder="Search workspace"></div><div class="top-actions"><button class="top-log" @click="modal='task'">＋ Log time</button><label class="import-action" title="Import CSV, PDF, JSON, or any file">⇧ Import<input type="file" accept="*/*" hidden @change="pickImport"></label><button @click="notice('No new notifications')">♢</button><button @click="dark=!dark">◐</button><button class="avatar" @click="profileOpen=!profileOpen">TEZ</button><div v-if="profileOpen" class="profile-menu"><b>TEZ</b><small>tez@mytracker.local</small><button @click="notice('Profile ready')">View profile</button><button @click="notice('Logged out locally')">Log out</button></div></div></header><main class="content"><section v-if="screen==='dashboard'" class="screen"><div class="page-head"><div><p class="eyebrow">{{new Date().toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase()}}</p><h1>Good morning, TEZ<span>.</span></h1><p class="muted">Your work, calendar, logs, and follow-ups in one place.</p></div><div class="month-select"><button @click="shift(-1)">‹</button><b>{{monthLabel}}</b><button @click="shift(1)">›</button></div></div><div class="hero-grid"><article class="focus-card"><div><p class="eyebrow">CURRENT FOCUS</p><h2>{{monthTasks[0]?.task||'Your next important thing'}}</h2><p class="muted">Keep the momentum moving.</p></div><button class="circle-arrow" @click="modal='task'">↗</button></article><div class="stat-card"><label>HOURS LOGGED</label><strong>{{hours.toFixed(1)}}</strong><small>{{monthLabel}}</small></div><div class="stat-card green"><label>DELIVERY RATE</label><strong>{{monthTasks.length?Math.round(done/monthTasks.length*100):0}}<small>%</small></strong><small>{{done}} of {{monthTasks.length}} tasks complete</small></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Work in flight</h3><p>Tasks that need attention</p></div><button class="text-button" @click="screen='reports'">View reports →</button></div><div v-if="monthTasks.length" class="compact-list"><div v-for="x in monthTasks.slice(0,6)" :key="x.id"><span class="dot" :class="tone(x.status)"></span><div><b>{{x.task}}</b><small>{{x.project||'No project'}} · {{x.hours}}h</small></div><span class="tag" :class="tone(x.status)">{{x.status}}</span></div></div><div v-else class="empty">No work in flight yet.</div></section><section class="panel analytics-card"><div class="panel-head"><div><h3>Work analytics</h3><p>Day, week, and month trends</p></div><button class="add-link" @click="screen='reports'">Details</button></div><div class="trend-chart"><i v-for="n in [30,48,38,70,55,82,64,88]" :key="n" :style="{height:n+'%'}"></i></div><div class="chart-labels"><span>Day</span><span>Week</span><span>Month</span></div><div class="todo-ring"><b>{{data.todos.filter(t=>t.status==='Completed').length}}</b><small>to-dos done</small></div></section></div></section><section v-else-if="screen==='logs'" class="screen"><div class="page-head"><div><p class="eyebrow">TIME CONTROL</p><h1>My timesheets / logs</h1><p class="muted">Manual entries and live timer sessions in one clear timeline.</p></div><button class="button primary" @click="modal='log'">＋ New log</button></div><div class="timer-strip"><div><b>{{Math.floor(elapsed/3600).toString().padStart(2,'0')}}:{{Math.floor(elapsed/60%60).toString().padStart(2,'0')}}:{{(elapsed%60).toString().padStart(2,'0')}}</b><small>{{timer?'Timer running':'Ready to track'}}</small></div><button class="button primary" @click="timer?stopTimer():startTimer()">{{timer?'End timer':'Start timer'}}</button></div><section class="panel table-panel"><table><thead><tr><th>Date</th><th>By</th><th>Work log</th></tr></thead><tbody><tr v-for="item in [...data.logs].reverse()" :key="item.id"><td>{{item.date}}</td><td>{{item.user}}</td><td>{{item.text}}</td></tr><tr v-if="!data.logs.length"><td colspan="3" class="empty">No logs captured yet.</td></tr></tbody></table></section></section><section v-else-if="screen==='todos'" class="screen"><div class="page-head"><div><p class="eyebrow">PERSONAL DELIVERY</p><h1>To-do board</h1><p class="muted">Drag items between statuses. Dates stay attached.</p></div><button class="button primary" @click="modal='todo'">＋ Add to-do</button></div><div class="kanban"><div v-for="status in ['Pending','In Progress','Completed']" :key="status" class="kanban-col" @dragover.prevent @drop="dropTodo(status as Todo['status'])"><div class="column-title"><b>{{status}}</b><em>{{data.todos.filter(t=>t.status===status).length}}</em></div><article v-for="item in data.todos.filter(t=>t.status===status)" :key="item.id" class="todo-card" draggable="true" @dragstart="dragStart(item)"><span class="tag" :class="tone(item.priority)">{{item.priority}}</span><h3>{{item.title}}</h3><p>{{item.detail}}</p><small>◷ {{item.due||'No due date'}}</small></article><button class="column-add" @click="modal='todo'">＋ Add item</button></div></div></section><section v-else-if="screen==='calendar'" class="screen"><div class="page-head"><div><p class="eyebrow">SCHEDULE</p><h1>Calendar</h1><p class="muted">Select a month and year to review dated work items.</p></div><button class="button primary" @click="modal='meeting'">＋ New event</button></div><section class="panel calendar-large"><div class="calendar-toolbar"><select v-model="month"><option v-for="m in months" :key="m" :value="m">{{new Date(`${m}-01`).toLocaleDateString('en-US',{month:'long',year:'numeric'})}}</option></select></div><div class="weekdays"><b v-for="d in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']" :key="d">{{d}}</b></div><div class="calendar-grid"><button v-for="day in 42" :key="day"><b>{{day<=31?day:''}}</b></button></div><p class="empty">Connected Google Calendar and Outlook events will appear here.</p></section></section><section v-else-if="screen==='reports'" class="screen"><div class="page-head"><div><p class="eyebrow">INSIGHTS</p><h1>Reports</h1><p class="muted">Overall and detailed reporting for the selected month.</p></div><button class="button primary" @click="modal='export'">⇩ Export report</button></div><div class="report-cards"><div class="report-number"><label>MONTH HOURS</label><strong>{{hours.toFixed(1)}}h</strong><p>{{monthLabel}}</p></div><div class="report-number"><label>OVERALL HOURS</label><strong>{{data.tasks.reduce((s,t)=>s+Number(t.hours||0),0).toFixed(1)}}h</strong><p>all months</p></div><div class="report-number"><label>COMPLETION</label><strong>{{done}}/{{monthTasks.length}}</strong><p>tasks delivered</p></div></div><section class="panel large-report"><div class="panel-head"><h3>Detailed category breakdown</h3></div><div v-if="monthTasks.length" class="bars"><div v-for="category in [...new Set(monthTasks.map(t=>t.category||'General'))]" :key="category"><b>{{category}}</b><i><span :style="{width:Math.max(8,monthTasks.filter(t=>(t.category||'General')===category).reduce((s,t)=>s+t.hours,0)/Math.max(1,hours)*100)+'%'}"></span></i></div></div><div v-else class="empty">Add time entries to build reports.</div></section></section><section v-else-if="screen==='integrations'" class="screen"><div class="page-head"><div><p class="eyebrow">CONNECTED WORKSPACE</p><h1>Integrations</h1><p class="muted">Connect calendars, docs, sheets, mail, notes, and design tools.</p></div></div><div class="integration-grid"><article v-for="item in ['Google Calendar','Google Docs','Google Sheets','Microsoft Outlook','Notion','Figma']" :key="item" class="integration-card"><b>{{item}}</b><small>Connect and sync work</small><button class="button" @click="notice(`${item} connection settings ready`)" >Connect</button></article></div></section><section v-else class="screen"><div class="page-head"><h1>{{screen}}</h1></div><section class="panel empty">This workspace area is ready for your connected records.</section></section></main></section><div v-if="modal==='task'||modal==='todo'||modal==='log'||modal==='meeting'||modal==='export'" class="backdrop"><form class="modal" @submit.prevent="modal==='task'?saveTask():modal==='todo'?addTodo():modal==='log'?saveManualLog():modal==='export'?exportCsv():notice('Event draft ready')"><button type="button" class="close" @click="modal=''">×</button><p class="eyebrow">{{modal.toUpperCase()}}</p><h2>{{modal==='task'?'Log time':modal==='todo'?'New to-do':modal==='log'?'New work log':modal==='export'?'Export report':'New calendar event'}}</h2><template v-if="modal==='export'"><select><option>Current month</option><option>Last 3 months</option><option>Last 6 months</option><option>Custom range</option></select></template><template v-else-if="modal==='task'||modal==='log'"><input v-model="task.task" required placeholder="What did you work on?"><input v-model="task.project" placeholder="Project"><input v-model.number="task.hours" type="number" min="0" step=".5" placeholder="Hours"><label class="date-field">Start date <input type="date"></label><label class="date-field">End date <input type="date"></label><label class="date-field">Start time <input type="time"></label><label class="date-field">End time <input type="time"></label></template><template v-else-if="modal==='todo'"><input v-model="todo.title" required placeholder="What needs doing?"><input v-model="todo.detail" placeholder="Details"><input v-model="todo.due" type="date"></template><template v-else><input required placeholder="Event title"><input type="datetime-local"><input placeholder="Meeting link"></template><button class="button primary full">{{modal==='export'?'Download report':'Continue'}}</button></form></div><div v-if="importOpen" class="backdrop"><section class="modal"><button class="close" @click="importOpen=false">×</button><p class="eyebrow">IMPORT REVIEW</p><h2>Review imported logs</h2><pre>{{importPreview}}</pre><div class="modal-actions"><button class="button" @click="importOpen=false">Cancel</button><button class="button primary" @click="applyImport">Import records</button></div></section></div><div v-if="toast" class="toast">{{toast}}</div></div></template>
